typedef struct {
    int channel;
    double volts;
} Sample;

double mean_volts(const Sample s[], int n)
{
    double total = 0.0;
    for (int i = 0; i < n; i++)
        total += s[i].volts;
    return total / n;   /* caller must ensure n >= 1 */
}
The count has to be passed in because inside the function s is a pointer and its length cannot be found with sizeof. const shows the function only reads the samples.

