questions.modelAnswer:
int push_front(struct node **head, int value)
{
    struct node *n = malloc(sizeof *n);
    if (n == NULL)
        return 0;
    n->data = value;
    n->next = *head;
    *head = n;
    return 1;
}

int length(const struct node *p)
{
    int count = 0;
    for (; p != NULL; p = p->next)
        count++;
    return count;
}
The double pointer lets push_front update the caller's head. length returns 0 for an empty list because the loop body never runs when p starts as NULL.

